function esc(s) {
  return s.replace(/[<>&"]/g, (ch) => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;' })[ch]);
}

// KML writer: one Placemark per feature.
export function placemark(feature) {
  const data = Object.entries(feature.properties)
    .map(([k, v]) => '<Data name="' + esc(k) + '"><value>' + esc(String(v)) + '</value></Data>')
    .join('');
  const [lon, lat] = feature.geometry?.coordinates ?? [NaN, NaN];
  return '<Placemark><ExtendedData>' + data + '</ExtendedData><Point><coordinates>' + lon + ',' + lat + '</coordinates></Point></Placemark>';
}
